code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    split = None
    for r in range(h):
        if len(set(grid[r])) == 1 and r == h // 2 - 1 and h % 2 == 1:
            split = ("h", r)
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1 and c == w // 2:
            split = ("v", c)
    if split is None:
        # Separator is the uniform central line; this also handles even-sized panels.
        for r in range(h):
            if len(set(grid[r])) == 1 and 2 * r == h - 1:
                split = ("h", r)
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1 and 2 * c == w - 1:
                split = ("v", c)
    if split is None:
        # Equal-sized halves separated by one full monochrome line.
        for r in range(h):
            if len(set(grid[r])) == 1 and r == h // 2 and h == 2 * r + 1:
                split = ("h", r)
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1 and c == w // 2 and w == 2 * c + 1:
                split = ("v", c)
    if split is None:
        raise ValueError("separator not found")
    axis, i = split
    if axis == "h":
        a, b = grid[:i], grid[i + 1:]
    else:
        a = [row[:i] for row in grid]
        b = [row[i + 1:] for row in grid]
    shared = set(x for row in a for x in row) & set(x for row in b for x in row)
    if not shared:
        raise ValueError("no common color")
    # The common color is the shared signal; non-signal cells are rendered as 4.
    return [[3 if a[r][c] == b[r][c] and a[r][c] in shared else 4
             for c in range(len(a[0]))] for r in range(len(a))]
'''
